def dedupe(listings: list[dict]) -> list[dict]:
    def key_of(item):
        return (' '.join(item['title'].split()).lower(), item['price'])

    best = {}
    for idx, item in enumerate(listings):
        key = key_of(item)
        current = best.get(key)
        if current is None or item['date'] < current[0]:
            best[key] = (item['date'], idx)

    winner_idx = {key: idx for key, (_, idx) in best.items()}

    return [item for idx, item in enumerate(listings) if winner_idx.get(key_of(item)) == idx]

